#include<stdio.h>
#define N 26
int main(int argc, char *argv[]) {
	int n;
	scanf("%d",&n);
	int a[N];
	int i,j;
	for(i=0;i<n;i++){
		scanf("%d",&a[i]);
	}
	//sort descending
	for(i=0;i<n-1;i++){
		int max=i;
		for(j=i+1;j<n;j++){
			if(a[j]>a[max])max=j;
		}
		if(max!=i){
			int tmp=a[max];
			a[max]=a[i];
			a[i]=tmp;
		}
	}
	long long max_length=a[0];
	int current_max=a[0];
	i=1;
	while(i<n){
		if(current_max<=1) break;
		if(a[i]>=current_max){
			max_length+=(current_max-1);
			current_max=current_max-1;
		}else{
			max_length+=a[i];
			current_max=a[i];
		}
		i++;
	}
	printf("%lld\n",max_length);
	return 0;
}

